package oidcadapter
import("context";"crypto/subtle";"errors";"net/http";"time";"github.com/coreos/go-oidc/v3/oidc";"golang.org/x/oauth2";"github.com/menerjangbadai/dashboard/internal/application")
type Provider struct{issuer string;config oauth2.Config;verifier *oidc.IDTokenVerifier;client *http.Client}
func New(ctx context.Context,issuer,clientID,secret,callback string)(*Provider,error){client:=&http.Client{Timeout:10*time.Second};ctx=oidc.ClientContext(ctx,client);p,e:=oidc.NewProvider(ctx,issuer);if e!=nil{return nil,errors.New("OIDC discovery unavailable or issuer mismatch")};return &Provider{issuer:issuer,client:client,config:oauth2.Config{ClientID:clientID,ClientSecret:secret,RedirectURL:callback,Endpoint:p.Endpoint(),Scopes:[]string{oidc.ScopeOpenID,"profile"}},verifier:p.Verifier(&oidc.Config{ClientID:clientID,SupportedSigningAlgs:[]string{oidc.RS256}})},nil}
func(p *Provider) AuthorizationURL(state,nonce,verifier string)string{return p.config.AuthCodeURL(state,oidc.Nonce(nonce),oauth2.S256ChallengeOption(verifier))}
func(p *Provider) Exchange(ctx context.Context,code,verifier,nonce string)(application.Identity,error){ctx=oidc.ClientContext(ctx,p.client);token,e:=p.config.Exchange(ctx,code,oauth2.VerifierOption(verifier));if e!=nil{return application.Identity{},errors.New("OIDC code exchange rejected")};raw,ok:=token.Extra("id_token").(string);if !ok{return application.Identity{},errors.New("ID token missing")};id,e:=p.verifier.Verify(ctx,raw);if e!=nil{return application.Identity{},errors.New("ID token verification rejected")};if id.Subject==""||nonce==""||subtle.ConstantTimeCompare([]byte(id.Nonce),[]byte(nonce))!=1{return application.Identity{},errors.New("OIDC nonce or subject invalid")};var claims struct{AZP string `json:"azp"`};if e=id.Claims(&claims);e!=nil{return application.Identity{},errors.New("ID token claims invalid")};if (len(id.Audience)>1 && claims.AZP=="") || (claims.AZP!="" && claims.AZP!=p.config.ClientID){return application.Identity{},errors.New("ID token authorized party invalid")};return application.Identity{Issuer:id.Issuer,Subject:id.Subject},nil}
func(p *Provider) Health(ctx context.Context)error{_,e:=oidc.NewProvider(oidc.ClientContext(ctx,p.client),p.issuer);return e}
